from aiida.engine import graph

from aiida.engine import Err, ExitCode, ExitCodeEnum, Ok, Result, task


class DivisionErrors(ExitCodeEnum):
    ZERO_DENOMINATOR = ExitCode(410, 'The denominator is zero.')


@task
def divide(numerator: float, denominator: float) -> Result[float, DivisionErrors]:
    if denominator == 0:
        return Err(DivisionErrors.ZERO_DENOMINATOR)
    return Ok(numerator / denominator)


@graph
def retry_ratio(numerator: float, denominator: float, max_retries: int = 3) -> float:
    attempt = 0
    value, error = divide.alias('initial')(numerator=numerator, denominator=denominator)
    while error is DivisionErrors.ZERO_DENOMINATOR and attempt < max_retries:
        denominator = denominator + 1.0
        attempt = attempt + 1
        value, error = divide.alias('retry')(numerator=numerator, denominator=denominator)
    return value
